declare const tools: { update_plan(args: {
  // Optional explanation for this plan update.
  explanation?: string;
  // The list of steps
  plan: Array<{
  // Step status.
  status: "pending" | "in_progress" | "completed";
  // Task step text.
  step: string;
}>;
}): Promise<unknown>; };
```

