            AccountSyncVersion::V2,
            Some(target.device_sync_policy_snapshot().1),
            Some(&proof),
            Some(&fresh_cut),
        )
        .unwrap();
    let rows = target.account_history(&peer, 10).unwrap();
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].id, EventId::new([73; 32]));
